model.metadata:
CREATE VIEW v_mc1_bansos AS
  SELECT nik, nama
  FROM bansos_dbb.master_penduduk;

CREATE VIEW v_mc1_dukcapil AS
  SELECT no_ktp, nama_lengkap
  FROM dukcapi_db.penduduk;

CREATE VIEW v_mc1_dtks AS
  SELECT kpm_id, no_ktp_kepala
  FROM dtsk_db.keluarga_penerima_manfaat;

CREATE VIEW v_mc1_bpjs AS
  SELECT peserta_id, no_ktp
  FROM bjps_db.peserta;

CREATE VIEW v_mc1_unknown AS
  SELECT nik, nama
  FROM oracle_erp_prod.master_penduduk;

CREATE VIEW v_mc2_bansos AS
  SELECT nik, nama
  FROM bansos_db.master_penduduks;

CREATE VIEW v_mc2_eligibility AS
  SELECT eligibility_id, nik
  FROM bansos_db.eligibilitys;

CREATE VIEW v_mc2_dukcapil AS
  SELECT no_ktp, nama_lengkap
  FROM dukcapil_db.penduduks;

CREATE VIEW v_mc2_kk AS
  SELECT no_kk, alamat_jalan
  FROM dukcapil_db.kartu_keluargaa;

CREATE VIEW v_mc2_kpm AS
  SELECT kpm_id, no_ktp_kepala
  FROM dtks_db.keluarga_penerima_manfaats;

CREATE VIEW v_mc2_bpjs AS
  SELECT peserta_id, no_ktp
  FROM bpjs_db.pesertas;

CREATE VIEW v_mc2_faskes AS
  SELECT faskes_id, nama_faskes
  FROM bpjs_db.fasilitas_kesehatann;

CREATE VIEW v_mc3_nik_bansos AS
  SELECT nikk, nama
  FROM bansos_db.master_penduduk;

CREATE VIEW v_mc3_penghasilan AS
  SELECT nik, penghasilann
  FROM bansos_db.master_penduduk;

CREATE VIEW v_mc3_nama_lengkap AS
  SELECT no_ktp, namalengkap
  FROM dukcapil_db.penduduk;

CREATE VIEW v_mc3_tgl_lahir AS
  SELECT no_ktp, tgl_lahirr
  FROM dukcapil_db.penduduk;

CREATE VIEW v_mc3_desil AS
  SELECT kpm_id, desil_kesejahtraan
  FROM dtks_db.keluarga_penerima_manfaat;

CREATE VIEW v_mc3_status_kmk AS
  SELECT kpm_id, status_kmiskinan
  FROM dtks_db.keluarga_penerima_manfaat;

CREATE VIEW v_mc3_kelas AS
  SELECT peserta_id, no_ktp, kelas_layanann
  FROM bpjs_db.peserta;

CREATE VIEW v_mc3_jenis_kep AS
  SELECT peserta_id, no_ktp, jenis_kepesrtaan
  FROM bpjs_db.peserta;

CREATE VIEW v_mc3_unknown_col AS
  SELECT no_ktp, xyz_random_col
  FROM dukcapil_db.penduduk;

CREATE VIEW v_mc_ok_bansos AS
  SELECT nik, nama, tanggal_lahir, pekerjaan, penghasilan
  FROM bansos_db.master_penduduk;
